-- LeadFlow staging sanitizer — SANITIZE. Run ONLY in the temporary cleaning database, after prepare.sql.
-- Every statement joins the marker table; on any other database it fails before changing anything.
UPDATE __staging_sanitize_marker m SET m.drift_ok = IF((SELECT COUNT(*) FROM (SELECT ic.table_name AS t, ic.column_name AS c FROM information_schema.columns ic LEFT JOIN __column_map cm ON cm.t = ic.table_name AND cm.c = ic.column_name WHERE ic.table_schema = DATABASE() AND ic.table_name NOT LIKE '\_\_%' AND cm.t IS NULL) u) = 0 AND (SELECT COUNT(*) FROM (SELECT cm.t, cm.c FROM __column_map cm LEFT JOIN information_schema.columns ic ON ic.table_schema = DATABASE() AND ic.table_name = cm.t AND ic.column_name = cm.c WHERE ic.column_name IS NULL) x) = 0, 1, 0);
SELECT 'STRUCTURE CHECK' AS step, m.drift_ok AS ok_1_means_safe_to_continue FROM __staging_sanitize_marker m;
SELECT 'NOT IN MAP' AS problem, u.t, u.c FROM (SELECT ic.table_name AS t, ic.column_name AS c FROM information_schema.columns ic LEFT JOIN __column_map cm ON cm.t = ic.table_name AND cm.c = ic.column_name WHERE ic.table_schema = DATABASE() AND ic.table_name NOT LIKE '\_\_%' AND cm.t IS NULL) u UNION ALL SELECT 'IN MAP BUT MISSING', x.t, x.c FROM (SELECT cm.t, cm.c FROM __column_map cm LEFT JOIN information_schema.columns ic ON ic.table_schema = DATABASE() AND ic.table_name = cm.t AND ic.column_name = cm.c WHERE ic.column_name IS NULL) x;
INSERT IGNORE INTO __src_phone (`real`) SELECT DISTINCT RIGHT(REGEXP_REPLACE(t.`phone`, '[^0-9]', ''), 10) FROM `always_on_enrollments` t JOIN __staging_sanitize_marker m ON m.drift_ok = 1 WHERE t.`phone` IS NOT NULL AND t.`phone` <> '' AND LENGTH(REGEXP_REPLACE(t.`phone`, '[^0-9]', '')) >= 7;
