INSERT INTO __map_phone (`real`, fake) SELECT x.`real`, CONCAT('+19992', LPAD(ROW_NUMBER() OVER (ORDER BY SHA2(CONCAT(m.salt, x.`real`), 256)), 6, '0')) FROM __src_phone x JOIN __staging_sanitize_marker m ON m.drift_ok = 1;
INSERT INTO __map_email (`real`, fake) SELECT x.`real`, CONCAT('u', LPAD(ROW_NUMBER() OVER (ORDER BY SHA2(CONCAT(m.salt, x.`real`), 256)), 6, '0'), '@example.invalid') FROM __src_email x JOIN __staging_sanitize_marker m ON m.drift_ok = 1;
INSERT INTO __map_name (`real`, fake) SELECT k.`real`, CONCAT(f.v, ' ', l.v, IF(k.k >= 1600, CONCAT(' ', k.k DIV 1600), '')) FROM (SELECT x.`real`, ROW_NUMBER() OVER (ORDER BY SHA2(CONCAT(m.salt, x.`real`), 256)) - 1 AS k FROM __src_name x JOIN __staging_sanitize_marker m ON m.drift_ok = 1) k JOIN __name_first f ON f.i = k.k % 40 JOIN __name_last l ON l.i = (k.k DIV 40) % 40;
INSERT INTO __map_team (`real`, fake) SELECT k.`real`, CONCAT('Team ', w.v, IF(k.k >= 30, CONCAT(' ', k.k DIV 30 + 1), '')) FROM (SELECT x.`real`, ROW_NUMBER() OVER (ORDER BY SHA2(CONCAT(m.salt, x.`real`), 256)) - 1 AS k FROM __src_team x JOIN __staging_sanitize_marker m ON m.drift_ok = 1) k JOIN __team_words w ON w.i = k.k % 30;
