UPDATE conversation_sessions cs JOIN __staging_sanitize_marker m ON m.drift_ok = 1 JOIN __synthetic_conversations sc ON sc.scenario = CASE
    WHEN cs.stage IN ('BOOKED','DONE','FUTURE_BOOKING','CALL_SCHEDULED','SCHEDULE_CONFIRM_SENT','SCHEDULE_CONFIRM_DONE')
      THEN ELT(1 + cs.id % 4, 'new_booking', 'reschedule', 'recurring', 'new_booking')
    WHEN cs.stage IN ('FOLLOW_UP_SCHEDULED','REACTIVATION','REACTIVATION_TIME','REVIEW_REBOOKING_REQUESTED','REVIEW_REBOOKING_DONE') THEN 'recurring'
    WHEN cs.stage IN ('REVIEW_REQUESTED','REVIEW_DONE','QUALITY_RATING_REQUESTED','QUALITY_MISSED_FOLLOWUP','QUALITY_RATING_DONE')
      THEN ELT(1 + cs.id % 2, 'complaint', 'general')
    WHEN cs.stage IN ('COLD','LOST','NOT_INTERESTED','VOICEMAIL','YELP_CONTACTED') THEN 'cancellation'
    WHEN cs.stage IN ('CLIENT_STATUS_INQUIRY','CLIENT_STATUS_INQUIRY_DONE') THEN 'reschedule'
    WHEN cs.stage IN ('INTERVIEW_LINK_SENT','INTERVIEW_NUDGE_1','INTERVIEW_NUDGE_2','INTERVIEW_LINK_DONE','HIRING_OUTBOUND') THEN 'cleaner_coordination'
    WHEN cs.stage IN ('RESOLVED','UNHANDLED') THEN 'general'
    ELSE 'quote' END AND sc.variant = cs.id % 3
  SET cs.messageHistory = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(sc.history, '__TS0__', CAST(COALESCE(NULLIF(cs.lastMessageTs, 0), UNIX_TIMESTAMP(cs.updatedAt) * 1000) - (sc.n - 1 - 0) * 600000 AS CHAR)), '__TS1__', CAST(COALESCE(NULLIF(cs.lastMessageTs, 0), UNIX_TIMESTAMP(cs.updatedAt) * 1000) - (sc.n - 1 - 1) * 600000 AS CHAR)), '__TS2__', CAST(COALESCE(NULLIF(cs.lastMessageTs, 0), UNIX_TIMESTAMP(cs.updatedAt) * 1000) - (sc.n - 1 - 2) * 600000 AS CHAR)), '__TS3__', CAST(COALESCE(NULLIF(cs.lastMessageTs, 0), UNIX_TIMESTAMP(cs.updatedAt) * 1000) - (sc.n - 1 - 3) * 600000 AS CHAR)), '__TS4__', CAST(COALESCE(NULLIF(cs.lastMessageTs, 0), UNIX_TIMESTAMP(cs.updatedAt) * 1000) - (sc.n - 1 - 4) * 600000 AS CHAR)), '__TS5__', CAST(COALESCE(NULLIF(cs.lastMessageTs, 0), UNIX_TIMESTAMP(cs.updatedAt) * 1000) - (sc.n - 1 - 5) * 600000 AS CHAR)), '{first}', COALESCE(NULLIF(SUBSTRING_INDEX(TRIM(cs.leadName), ' ', 1), ''), 'there')),
      cs.lastMessageText = LEFT(REPLACE(sc.last_text, '{first}', COALESCE(NULLIF(SUBSTRING_INDEX(TRIM(cs.leadName), ' ', 1), ''), 'there')), 255),
      cs.lastMessageRole = sc.last_role,
      cs.messageCount = sc.n;
