UPDATE `voice_calls` t JOIN __staging_sanitize_marker m ON m.drift_ok = 1 SET t.`outcome` = REGEXP_REPLACE(REGEXP_REPLACE(CAST(t.`outcome` AS CHAR), '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}', 'info@example.invalid'), '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})', '+19992000000') WHERE CAST(t.`outcome` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`outcome` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}';
UPDATE `voice_calls` t JOIN __staging_sanitize_marker m ON m.drift_ok = 1 SET t.`successEvaluation` = REGEXP_REPLACE(REGEXP_REPLACE(CAST(t.`successEvaluation` AS CHAR), '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}', 'info@example.invalid'), '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})', '+19992000000') WHERE CAST(t.`successEvaluation` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`successEvaluation` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}';
UPDATE app_settings t JOIN __staging_sanitize_marker m ON m.drift_ok = 1 SET t.`value` = '' WHERE LOWER(t.`key`) REGEXP 'token|secret|password|api_?key|webhook|credential|private|signing';
SELECT 'SANITIZE COMPLETE' AS step, m.drift_ok AS ok FROM __staging_sanitize_marker m;
